def semver_sort(versions):
    def parse_version(version):
        # Split off build metadata (everything after '+')
        if '+' in version:
            version_part, _ = version.split('+', 1)
        else:
            version_part = version

        # Split off pre-release (everything after '-')
        if '-' in version_part:
            base_part, prerelease_part = version_part.split('-', 1)
        else:
            base_part = version_part
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = base_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            # Convert to tuples (is_numeric, value) for comparison
            prerelease_identifiers = []
            for identifier in identifiers:
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def compare_key(item):
        index, version = item
        major, minor, patch, prerelease_identifiers = parse_version(version)

        # For sorting: a version without pre-release sorts after one with pre-release
        # So we use (major, minor, patch, 0, ()) for no pre-release
        # and (major, minor, patch, 1, prerelease_identifiers) for with pre-release
        if prerelease_identifiers is None:
            return (major, minor, patch, 1, ())
        else:
            return (major, minor, patch, 0, tuple(prerelease_identifiers))

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=compare_key)
    return [version for _, version in sorted_versions]

